// Speaker Button Functionality  //generated by Copilot
const speakerBtn = document.getElementById('speakerBtn');

speakerBtn.addEventListener('click', () => {
    const word = document.querySelector('.card-word').textContent;
    
    // Use Web Speech API to speak the word
    const utterance = new SpeechSynthesisUtterance(word);
    utterance.rate = 1;
    utterance.pitch = 1;
    window.speechSynthesis.speak(utterance);
});

// copilot code to create card "flip"
function flipCard() {
  const back = document.querySelector('.card-back');
  const buttons = document.getElementById('difficulty-buttons');
  
  if (back.classList.contains('hidden')) {
    back.classList.remove('hidden');
    buttons.classList.remove('hidden');
  }
}